# MECH 361 (Fluid Mechanics II, Dr. Essel, Fall 2026) — theory question bank.
# Written from the lecture slides (Munson 9e: Ch 1 review, 6.1–6.6, 6.8–6.9, 8.1.2, 8.3–8.5, 9.1–9.4, 11.1–11.6).
C = "mech361"
L = lambda n, t: f"Lecture {n:02d} – {t}" if isinstance(n, int) else f"Lecture {n} – {t}"
Q = []
def mcq(id, topic, q, choices, ans, exp, src): Q.append(dict(id=f"m361-{id}", course=C, topic=topic, type="mcq", question=q, choices=choices, answer=ans, explanation=exp, source=src))
def tf(id, topic, q, ans, exp, src): Q.append(dict(id=f"m361-{id}", course=C, topic=topic, type="tf", question=q, answer=ans, explanation=exp, source=src))
def sa(id, topic, q, ans, exp, src, kw=()): Q.append(dict(id=f"m361-{id}", course=C, topic=topic, type="short", question=q, answer=ans, explanation=exp, source=src, keywords=list(kw)))

T = "Fluid basics (Ch 1)"; s = L(2, "Introduction & Fluid Kinematics")
tf("c1-01", T, "A solid deforms when a shear stress is applied, but unlike a fluid its deformation is not continuous.", True, "A fluid is defined as a substance that deforms continuously under shear stress, however small.", s)
mcq("c1-02", T, "For a Newtonian fluid, shear stress is:", ["Linearly proportional to the rate of shear strain, $\\tau=\\mu\\,du/dy$", "Proportional to the shear strain itself", "Independent of the velocity gradient", "Proportional to $(du/dy)^2$"], 0, "The constant of proportionality is the dynamic viscosity $\\mu$. Water, air and oil are Newtonian.", s)
mcq("c1-03", T, "Ketchup and paint get easier to stir the harder you shear them. They are:", ["Shear-thinning (pseudoplastic)", "Shear-thickening (dilatant)", "Bingham plastics", "Newtonian"], 0, "Shear-thinning: apparent viscosity decreases as shear rate increases.", s)
mcq("c1-04", T, "A water–cornstarch mixture (or quicksand) is an example of a:", ["Shear-thickening (dilatant) fluid", "Shear-thinning fluid", "Bingham plastic", "Newtonian fluid"], 0, "Apparent viscosity increases with shear rate.", s)
tf("c1-05", T, "Toothpaste and mayonnaise can withstand a finite yield stress without flowing, which makes them Bingham plastics.", True, "Below $\\tau_{yield}$ they behave like a solid. Once it is exceeded they flow.", s)
sa("c1-06", T, "List the five basic laws used to analyze fluid problems.", "Conservation of mass, Newton's 2nd law (linear momentum), angular momentum principle, 1st law of thermodynamics, 2nd law of thermodynamics.", "Not every problem needs all five. Some also need an equation of state (e.g. $p=\\rho RT$) and boundary conditions such as no-slip.", s, ["mass", "linear momentum", "angular momentum", "1st law", "2nd law"])
mcq("c1-07", T, "Which statement about a control volume is TRUE?", ["Mass can cross its control surface", "It always contains the same fluid particles", "The basic laws apply to it directly without modification", "Its boundary can never move"], 0, "A system is a fixed mass (no mass crosses its boundary). A CV is a region in space and mass flows through it. The basic laws are written for systems and must be converted (Reynolds transport theorem) to apply to a CV.", s)
mcq("c1-08", T, "Following one fluid particle as it moves through the flow is the:", ["Lagrangian approach", "Eulerian approach", "Integral approach", "Control-volume approach"], 0, "The Eulerian approach describes the field at fixed points in space and is the one usually used in fluid mechanics.", s)
tf("c1-09", T, "The integral approach gives the detailed velocity distribution in a pipe, while the differential approach only gives bulk quantities like average velocity.", False, "It's the reverse: integral → gross/bulk behaviour (e.g. $U_{av}=Q/A$, drag); differential → detailed field (e.g. $u(r)$).", s)

T = "Fluid kinematics (6.1)"; s3 = L(3, "Fluid Kinematics"); s4 = L(4, "Fluid Kinematics"); s2 = L(2, "Fluid Kinematics")
tf("k-01", T, "A flow whose velocity at every point does not change with time is steady, even if the velocity varies from point to point.", True, "Steady = no time dependence. Uniform = no spatial variation over a region. These are independent properties.", s2)
mcq("k-02", T, "The material derivative of velocity, $\\frac{D\\vec V}{Dt}=\\frac{\\partial \\vec V}{\\partial t}+(\\vec V\\cdot\\nabla)\\vec V$, consists of:", ["Local acceleration + convective acceleration", "Normal acceleration + tangential acceleration", "Linear acceleration + angular acceleration", "Pressure acceleration + viscous acceleration"], 0, "Local = unsteadiness at a point. Convective = change because the particle moves to a place with a different velocity.", s2)
tf("k-03", T, "In a steady flow, fluid particles cannot accelerate.", False, "Steady flow kills the local term only. Convective acceleration $(\\vec V\\cdot\\nabla)\\vec V$ can still be nonzero, e.g. flow speeding up through a nozzle.", s2)
sa("k-04", T, "Name the four types of motion a fluid element can undergo.", "Translation, rotation, linear deformation, and angular deformation (distortion).", "Translation + rotation are rigid-body motion. Linear and angular deformation change the element's shape or size.", s3, ["translation", "rotation", "linear deformation", "angular deformation"])
mcq("k-05", T, "The volumetric dilatation rate $\\frac{1}{V}\\frac{dV}{dt}$ equals:", ["$\\nabla\\cdot\\vec V=\\partial u/\\partial x+\\partial v/\\partial y+\\partial w/\\partial z$", "$\\nabla\\times\\vec V$", "$\\frac12(\\partial v/\\partial x-\\partial u/\\partial y)$", "$\\partial v/\\partial x+\\partial u/\\partial y$"], 0, "It is the sum of the three linear strain rates $\\varepsilon_{xx}+\\varepsilon_{yy}+\\varepsilon_{zz}$.", s3)
mcq("k-06", T, "What is the volumetric dilatation rate in an incompressible flow?", ["Zero", "Constant but nonzero", "One", "Negative"], 0, "Incompressible means fluid elements keep their volume: $\\nabla\\cdot\\vec V=0$, which is the incompressible continuity equation. (Engineers at Work 6.1)", s4)
tf("k-07", T, "When air is compressed in a cylinder by a piston, the volumetric dilatation rate of the air is negative.", True, "Fluid elements shrink, so $\\frac1V\\frac{dV}{dt}<0$. (Engineers at Work 6.1)", s4)
mcq("k-08", T, "Vorticity $\\vec\\zeta$ is related to the angular velocity $\\vec\\omega$ of a fluid particle by:", ["$\\vec\\zeta=2\\vec\\omega=\\nabla\\times\\vec V$", "$\\vec\\zeta=\\vec\\omega$", "$\\vec\\zeta=\\tfrac12\\vec\\omega$", "$\\vec\\zeta=\\nabla\\cdot\\vec V$"], 0, "Vorticity is twice the rate of rotation and equals the curl of the velocity.", s3)
mcq("k-09", T, "For a 2-D flow in the $x$–$y$ plane, the flow is irrotational when:", ["$\\partial v/\\partial x=\\partial u/\\partial y$", "$\\partial u/\\partial x=-\\partial v/\\partial y$", "$\\partial v/\\partial x=-\\partial u/\\partial y$", "$u=v$"], 0, "$\\zeta_z=\\partial v/\\partial x-\\partial u/\\partial y=0$.", s3)
tf("k-10", T, "The 2-D velocity field $u=3x-y$, $v=2y$ is irrotational.", False, "$\\zeta_z=\\partial v/\\partial x-\\partial u/\\partial y=0-(-1)=1\\neq0$, so it is rotational. (Engineers at Work 6.2)", L(5, "Kinematics & Conservation of Mass"))
mcq("k-11", T, "The rate of angular deformation (rate of shearing strain) in the $x$–$y$ plane is:", ["$\\dot\\gamma=\\partial v/\\partial x+\\partial u/\\partial y$", "$\\dot\\gamma=\\partial v/\\partial x-\\partial u/\\partial y$", "$\\dot\\gamma=\\partial u/\\partial x+\\partial v/\\partial y$", "$\\dot\\gamma=\\tfrac12(\\partial v/\\partial x-\\partial u/\\partial y)$"], 0, "It is the rate of change of the angle between two initially perpendicular lines. The shear strain rate $\\varepsilon_{xy}$ is half of it.", s4)
tf("k-12", T, "For the Couette-type flow $u=Uy/b$ between plates, the flow is both rotational and undergoing angular deformation.", True, "$\\partial u/\\partial y=U/b\\neq0$ gives $\\zeta_z=-U/b$ (rotational) and $\\dot\\gamma=U/b$ (deforming). Dilatation is zero. (Example 6.3)", s4)
mcq("k-13", T, "What is the simplest type of motion a fluid particle can undergo?", ["Translation", "Rotation", "Linear deformation", "Angular deformation"], 0, "Engineers at Work 6.2.", s4)
tf("k-14", T, "The strain-rate tensor is symmetric, with linear (normal) strain rates on its diagonal and shear strain rates off-diagonal.", True, "$\\varepsilon_{ij}=\\varepsilon_{ji}=\\tfrac12(\\partial u_i/\\partial x_j+\\partial u_j/\\partial x_i)$.", s4)

T = "Continuity & stream function (6.2)"; s = L(5, "Kinematics & Conservation of Mass")
mcq("cm-01", T, "The general differential continuity equation is:", ["$\\partial\\rho/\\partial t+\\nabla\\cdot(\\rho\\vec V)=0$", "$\\nabla\\cdot\\vec V=0$", "$\\nabla\\times\\vec V=0$", "$\\rho\\,D\\vec V/Dt=-\\nabla p$"], 0, "Steady compressible flow: $\\nabla\\cdot(\\rho\\vec V)=0$. Incompressible flow: $\\nabla\\cdot\\vec V=0$.", s)
mcq("cm-02", T, "For steady compressible flow, the continuity equation reduces to:", ["$\\nabla\\cdot(\\rho\\vec V)=0$", "$\\nabla\\cdot\\vec V=0$", "$\\partial\\rho/\\partial t=0$ only", "$\\rho\\vec V=$ constant everywhere"], 0, "Only the time-derivative term drops out. Density can still vary in space.", s)
mcq("cm-03", T, "In 2-D incompressible Cartesian flow, the stream function is defined by:", ["$u=\\partial\\psi/\\partial y,\\ v=-\\partial\\psi/\\partial x$", "$u=-\\partial\\psi/\\partial y,\\ v=\\partial\\psi/\\partial x$", "$u=\\partial\\psi/\\partial x,\\ v=\\partial\\psi/\\partial y$", "$\\vec V=\\nabla\\psi$"], 0, "This definition satisfies continuity automatically, so two unknowns ($u$, $v$) become one ($\\psi$).", s)
tf("cm-04", T, "In 2-D incompressible flow, lines of constant stream function are streamlines.", True, "Along a streamline $d\\psi=0$. (Engineers at Work 6.2)", s)
tf("cm-05", T, "The volume flow rate per unit width between two streamlines equals the difference in their stream-function values, $q=\\psi_2-\\psi_1$.", True, "No flow crosses a streamline, so $Q$ between them is fixed by $\\Delta\\psi$.", s)
mcq("cm-06", T, "In polar coordinates the stream function gives:", ["$v_r=\\frac1r\\frac{\\partial\\psi}{\\partial\\theta},\\ v_\\theta=-\\frac{\\partial\\psi}{\\partial r}$", "$v_r=\\frac{\\partial\\psi}{\\partial r},\\ v_\\theta=\\frac1r\\frac{\\partial\\psi}{\\partial\\theta}$", "$v_r=-\\frac{\\partial\\psi}{\\partial r},\\ v_\\theta=\\frac1r\\frac{\\partial\\psi}{\\partial\\theta}$", "$v_r=r\\frac{\\partial\\psi}{\\partial\\theta},\\ v_\\theta=\\frac{\\partial\\psi}{\\partial r}$"], 0, "Compare the velocity potential, which gives $v_r=\\partial\\phi/\\partial r$ and $v_\\theta=\\frac1r\\partial\\phi/\\partial\\theta$.", s)
sa("cm-07", T, "How do you check whether a stream function exists for a given 2-D velocity field?", "Check that the flow satisfies incompressible continuity: $\\partial u/\\partial x+\\partial v/\\partial y=0$. If it does, $\\psi$ exists.", "The stream function is built to satisfy continuity, so it exists only for incompressible (or steady 2-D) flows that obey it. Irrotationality is not required. (Example 6.5)", s, ["continuity satisfied", "divergence zero"])
mcq("cm-08", T, "For $\\psi=4x^2y-y^3$, the velocity component $v$ is:", ["$-8xy$", "$4x^2-3y^2$", "$8xy$", "$-4x^2+3y^2$"], 0, "$v=-\\partial\\psi/\\partial x=-8xy$. (Engineers at Work 6.2)", s)

T = "Momentum & inviscid flow (6.3–6.4)"; s6 = L(6, "Linear Momentum & Inviscid Flow"); s7 = L(7, "LME & Potential Flow")
mcq("mo-01", T, "The forces acting on a differential fluid element are:", ["Body forces (gravity) and surface forces (normal and shear stresses)", "Only pressure forces", "Only gravity", "Inertial and centrifugal forces"], 0, "Surface forces come from the stress field: normal stresses $\\sigma$ and shear stresses $\\tau$.", s6)
tf("mo-02", T, "In the stress notation $\\sigma_{yx}$, the first index gives the direction of the normal to the plane and the second gives the direction the stress acts in.", True, "So $\\tau_{yx}$ acts on a plane normal to $y$, in the $x$-direction.", s6)
mcq("mo-03", T, "The general differential momentum equations written in terms of stresses are called:", ["Cauchy's equations", "Euler's equations", "Navier–Stokes equations", "Bernoulli equations"], 0, "Substituting $\\sigma=-p$, $\\tau=0$ gives Euler's equations. Substituting Newtonian stresses gives Navier–Stokes.", s6)
mcq("mo-04", T, "A flow is called inviscid when:", ["Shearing stresses are negligible", "The velocity is negligible", "No acceleration occurs", "The density is constant"], 0, "Engineers at Work: with $\\mu\\approx0$ the only stress is pressure.", s7)
mcq("mo-05", T, "The equations of motion for an inviscid flow are commonly called:", ["Euler's equations", "Cauchy's equations", "Newton's equations", "Stokes' equations"], 0, "$\\rho\\,g-\\nabla p=\\rho\\,D\\vec V/Dt$.", s7)
tf("mo-06", T, "All inviscid flows are irrotational, but not all irrotational flows are inviscid.", False, "The first part is false: an inviscid flow can still be rotational (vorticity is carried along, not destroyed, when viscosity is zero). In this course, irrotational (potential) flows are modelled as inviscid. (Engineers at Work)", s7)
sa("mo-07", T, "State the assumptions behind the Bernoulli equation $p+\\tfrac12\\rho V^2+\\gamma z=$ const.", "Inviscid, steady, incompressible flow, applied along a streamline. If the flow is also irrotational, the constant is the same everywhere (any two points).", "Bernoulli comes from integrating Euler's equation along a streamline.", s6, ["inviscid", "steady", "incompressible", "along a streamline", "irrotational → anywhere"])
tf("mo-08", T, "For irrotational flow, the Bernoulli equation can be applied between any two points, not just along one streamline.", True, "Irrotationality makes the Bernoulli constant uniform throughout the flow field.", s7)

T = "Potential flow (6.5–6.6)"; s7 = L(7, "Potential Flow – Uniform Flow"); s8 = L(8, "Source, Sink & Vortex"); s9 = L(9, "Vortex, Doublet & Superposition"); s10 = L(10, "Superposition"); s11 = L(11, "Superposition & Navier–Stokes")
sa("pf-01", T, "What three properties define a potential flow, and which equation governs it?", "Inviscid, incompressible and irrotational. Governed by Laplace's equation $\\nabla^2\\phi=0$ (and $\\nabla^2\\psi=0$ in 2-D).", "Velocity comes from $\\vec V=\\nabla\\phi$. Pressure then comes from Bernoulli.", s7, ["inviscid", "incompressible", "irrotational", "Laplace"])
mcq("pf-02", T, "The major advantage of Laplace's equation over the momentum equations is that it is:", ["Linear, so solutions can be superposed", "Nonlinear, so it captures turbulence", "First order", "Valid for viscous flows"], 0, "Linearity lets you add basic solutions (uniform flow, source, vortex, doublet) to build complex flows.", s9)
tf("pf-03", T, "The velocity potential exists only for irrotational flows, while the stream function (2-D) exists for any incompressible flow.", True, "$\\vec V=\\nabla\\phi$ automatically gives $\\nabla\\times\\vec V=0$. $\\psi$ only needs continuity.", s7)
tf("pf-04", T, "In a potential flow, lines of constant $\\phi$ (equipotential lines) are perpendicular to streamlines.", True, "$\\nabla\\phi$ is parallel to $\\vec V$, which is tangent to streamlines, so equipotentials cross streamlines at right angles.", s7)
mcq("pf-05", T, "For a 2-D source of strength $m$ (where $m=q/2\\pi$), the radial velocity is:", ["$v_r=m/r$", "$v_r=mr$", "$v_r=m/r^2$", "$v_r=m$"], 0, "$v_r=q/(2\\pi r)$ and $v_\\theta=0$. Velocity becomes infinite at $r=0$ (a singularity).", s8)
mcq("pf-06", T, "The streamlines of a free vortex are:", ["Concentric circles", "Radial lines", "Parallel straight lines", "Hyperbolas"], 0, "$v_r=0$ and $v_\\theta=K/r$.", s8)
mcq("pf-07", T, "Which statement about free and forced vortices is correct?", ["A free vortex ($v_\\theta=K/r$) is irrotational. A forced vortex ($v_\\theta=\\omega r$) is rotational.", "Both are irrotational", "A free vortex is rotational. A forced vortex is irrotational.", "Both are rotational"], 0, "Drain swirl and hurricanes (outer region) ≈ free vortex. A rotating tank of liquid = forced vortex.", s9)
sa("pf-08", T, "What is a combined (Rankine) vortex, and give an example.", "A forced (rigid-body, rotational) vortex core surrounded by a free (irrotational) vortex outside it. Example: a tornado.", "Velocity rises linearly with $r$ in the core, peaks at the core edge, then decays as $1/r$.", s9, ["forced core", "free outer", "tornado"])
mcq("pf-09", T, "Circulation $\\Gamma$ is defined as:", ["The line integral of the tangential velocity around a closed curve, $\\oint \\vec V\\cdot d\\vec s$", "The flow rate through a closed curve", "The curl of the velocity at a point", "The area integral of pressure"], 0, "For a free vortex $\\Gamma=2\\pi K$, and it is nonzero only around paths that enclose the singularity.", s9)
tf("pf-10", T, "The circulation around any closed path that does NOT enclose the centre of a free vortex is zero.", True, "The free vortex is irrotational everywhere except at the singularity at $r=0$.", s9)
mcq("pf-11", T, "A doublet is formed by:", ["Bringing a source and an equal sink together ($a\\to0$) while $q\\to\\infty$ with $qa$ fixed", "Adding a vortex to a uniform flow", "Adding two sources of equal strength", "Adding a source to a uniform flow"], 0, "Its streamlines are circles tangent to the axis at the origin.", s9)
mcq("pf-12", T, "Uniform flow + a source produces flow around a:", ["Half-body (Rankine half-body)", "Circular cylinder", "Closed Rankine oval", "Rotating cylinder"], 0, "It has one stagnation point upstream of the source, and the body stays open downstream.", s9)
mcq("pf-13", T, "Uniform flow + a source and sink of equal strength gives a:", ["Rankine oval (closed body)", "Half-body", "Circular cylinder", "Free vortex"], 0, "It has two stagnation points, one upstream and one downstream.", s10)
mcq("pf-14", T, "Potential flow around a stationary circular cylinder is built from:", ["Uniform flow + doublet", "Uniform flow + source", "Uniform flow + vortex only", "Source + sink + vortex"], 0, "Adding a vortex as well gives a rotating cylinder with lift.", s10)
mcq("pf-15", T, "On the surface of a cylinder in potential flow, the maximum speed is ___ and occurs at the top and bottom ($\\theta=\\pm90^\\circ$).", ["$2U$", "$U$", "$\\sqrt2\\,U$", "$4U$"], 0, "$v_\\theta=-2U\\sin\\theta$ on $r=a$.", s10)
sa("pf-16", T, "State d'Alembert's paradox.", "In inviscid (potential) flow, a body such as a cylinder experiences zero drag, which contradicts experiments where real bodies have significant drag.", "The symmetric potential-flow pressure distribution cancels out. Real flows have boundary layers and separation that break this symmetry.", s10, ["zero drag", "inviscid", "contradicts experiment", "separation"])
mcq("pf-17", T, "Adding a vortex of circulation $\\Gamma$ to the flow around a cylinder produces:", ["Lift $= -\\rho U\\Gamma$ per unit length, but still zero drag", "Drag but no lift", "Both lift and drag", "Neither lift nor drag"], 0, "This is the Magnus effect (Kutta–Joukowski lift). D'Alembert's paradox still holds for drag.", s11)
mcq("pf-18", T, "For a rotating cylinder, as $\\Gamma/(4\\pi Ua)$ increases beyond 1, the stagnation point:", ["Leaves the surface and moves into the flow", "Moves to the front of the cylinder", "Splits into four points", "Disappears entirely"], 0, "There are three cases: two stagnation points on the surface (<1), one coincident point at the bottom (=1), one point off the body (>1).", s11)
tf("pf-19", T, "The Magnus effect is the development of lift on a rotating body in a crossflow, e.g. a curving soccer ball.", True, "Rotation adds circulation, and circulation in a uniform stream produces lift.", s11)

T = "Navier–Stokes & exact solutions (6.8–6.9)"; s11 = L(11, "Navier–Stokes"); s12 = L(12, "Viscous Flow"); s13 = L("13-14", "Viscous Flow Examples")
mcq("ns-01", T, "The Navier–Stokes equations are:", ["Second-order, nonlinear partial differential equations with no general analytical solution", "First-order linear ODEs", "Linear PDEs that can be superposed", "Algebraic equations"], 0, "The nonlinear convective-acceleration term $(\\vec V\\cdot\\nabla)\\vec V$ is the main difficulty.", s11)
sa("ns-02", T, "Name three situations where Navier–Stokes has analytical solutions.", "(1) Incompressible irrotational (potential) flow. (2) Fully developed flows where the convective acceleration is zero, e.g. pipe or channel flow. (3) Stokes (creeping) flow where inertia is negligible next to viscous forces.", "In each case the nonlinear term vanishes or becomes negligible.", s11, ["potential flow", "fully developed", "Stokes/creeping flow"])
mcq("ns-03", T, "For incompressible 3-D viscous flow, Navier–Stokes plus continuity give:", ["4 equations for 4 unknowns ($u, v, w, p$)", "3 equations for 3 unknowns", "4 equations for 3 unknowns", "1 equation for 1 unknown"], 0, "3 momentum equations + continuity, with unknowns $u$, $v$, $w$, $p$.", s11)
tf("ns-04", T, "For a Newtonian incompressible fluid, the viscous stress tensor is linearly proportional to the strain-rate tensor: $\\tau_{ij}=2\\mu\\varepsilon_{ij}$.", True, "This constitutive relation turns the Cauchy equations into Navier–Stokes.", s11)
mcq("ns-05", T, "The no-slip boundary condition states that at a solid wall:", ["The fluid velocity equals the wall velocity", "The shear stress is zero", "The normal velocity is maximum", "The pressure is zero"], 0, "For a stationary wall, $\\vec V=0$ at the wall.", s11)
mcq("ns-06", T, "At a free surface (free-slip condition), which holds?", ["The shear stress is zero", "The velocity is zero", "The pressure gradient is infinite", "The vorticity is maximum"], 0, "Free surface: no shear, $\\partial u/\\partial y=0$, and the pressure equals the atmospheric pressure.", s11)
sa("ns-07", T, "What two conditions must hold at the interface between two immiscible fluids?", "The velocities of the two fluids are equal (no slip between them), and the shear stress parallel to the interface is the same in both fluids.", "These conditions couple the two velocity profiles.", s11, ["equal velocity", "equal shear stress"])
mcq("ns-08", T, "Steady, fully developed laminar flow between two fixed parallel plates (plane Poiseuille flow) has a velocity profile that is:", ["Parabolic, with maximum at the centreline", "Linear", "Uniform", "Logarithmic"], 0, "$u=\\frac{1}{2\\mu}\\frac{dp}{dx}(y^2-h^2)$.", s12)
tf("ns-09", T, "In pressure-driven flow between fixed plates, the pressure gradient $dp/dx$ is negative in the flow direction.", True, "Pressure falls along the flow to overcome viscous wall shear.", s12)
mcq("ns-10", T, "Couette flow with zero pressure gradient between a fixed plate and a plate moving at $U$ has a velocity profile that is:", ["Linear, $u=Uy/b$", "Parabolic", "Logarithmic", "Uniform"], 0, "A nonzero $dp/dx$ adds a parabolic part on top of the linear one.", s13)
mcq("ns-11", T, "Hagen–Poiseuille (laminar pipe) flow has volume flow rate:", ["$Q=\\dfrac{\\pi R^4\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi R^2\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi D^4\\Delta p}{8\\mu\\ell}$", "$Q=\\dfrac{\\pi R^4\\Delta p}{4\\mu\\ell}$"], 0, "The fourth-power dependence on $R$ means halving the radius cuts $Q$ by a factor of 16 at the same $\\Delta p$.", s13)
tf("ns-12", T, "In laminar pipe flow, the average velocity is half the centreline (maximum) velocity.", True, "$V_{avg}=u_{max}/2$ for the parabolic profile $u=u_{max}(1-r^2/R^2)$.", s13)

T = "Pipe flow & turbulence (Ch 8)"; s15 = L(15, "Viscous Flow in Pipes"); s16 = L(16, "Viscous Flow in Pipes"); s17 = L(17, "Viscous Flow in Pipes")
mcq("pp-01", T, "For pipe flow (based on $D$ and average velocity), the flow is typically laminar below Re ≈", ["2100", "500", "5×10⁵", "10,000"], 0, "Laminar < 2100, transitional 2100–4000, turbulent > 4000 (the values used in this course).", s15)
tf("pp-02", T, "The distinguishing feature of turbulence is the presence of random velocity fluctuations. Without them there is no turbulence.", True, "This is why we use Reynolds decomposition $u=\\bar u+u'$.", s15)
mcq("pp-03", T, "Reynolds decomposition splits an instantaneous variable into:", ["A time-mean part plus a fluctuating part", "A laminar part plus a turbulent part", "A pressure part plus a viscous part", "Normal and shear components"], 0, "$u=\\bar u+u'$, with $\\overline{u'}=0$.", s15)
mcq("pp-04", T, "Turbulence intensity is defined as:", ["$u'_{rms}/\\bar u$", "$\\bar u/u'_{rms}$", "$\\overline{u'v'}$", "$\\bar u/U_{max}$"], 0, "The RMS fluctuation as a fraction of the mean velocity.", s15)
tf("pp-05", T, "The time average of a fluctuation is zero, but the time average of a product of two fluctuations, $\\overline{u'v'}$, generally is not.", True, "That nonzero correlation is the Reynolds shear stress.", s15)
mcq("pp-06", T, "Averaging the Navier–Stokes equations (RANS) creates extra unknowns called:", ["Reynolds stresses $-\\rho\\overline{u_i'u_j'}$", "Viscous stresses", "Body forces", "Pressure fluctuations only"], 0, "The diagonal terms are normal Reynolds stresses (they sum to 2× the turbulent kinetic energy). Off-diagonal terms are shear stresses.", s15)
sa("pp-07", T, "What is the turbulence closure problem?", "The RANS equations have more unknowns than equations: 4 mean variables plus 6 independent Reynolds stresses (10 unknowns) against only 4 equations. The Reynolds stresses must be modelled (e.g. eddy viscosity) to close the system.", "No exact equation exists for the new unknowns without introducing even more unknowns.", s15, ["more unknowns than equations", "Reynolds stresses", "need a model"])
mcq("pp-08", T, "In the eddy-viscosity model, the total shear stress in turbulent flow is:", ["$\\tau=(\\mu+\\eta)\\,d\\bar u/dy$, i.e. viscous plus turbulent ($-\\rho\\overline{u'v'}=\\eta\\,d\\bar u/dy$)", "$\\tau=\\mu\\,d\\bar u/dy$ only", "$\\tau=-\\rho\\overline{u'v'}$ only", "$\\tau=\\rho\\bar u^2$"], 0, "The eddy viscosity $\\eta$ is a flow property, not a fluid property. It is usually much larger than $\\mu$ away from the wall.", s16)
mcq("pp-09", T, "From the wall outward, the three layers of a turbulent velocity profile are:", ["Viscous sublayer → overlap (log) layer → outer layer", "Outer layer → viscous sublayer → overlap layer", "Laminar layer → transition layer → wake", "Boundary layer → core → wake"], 0, "In the viscous sublayer viscous stress dominates. In the outer layer turbulent stress dominates. The log law holds in the overlap.", s16)
tf("pp-10", T, "A turbulent pipe velocity profile is flatter (fuller) across the core than the laminar parabolic profile, with a steeper gradient at the wall.", True, "Turbulent mixing evens out momentum across the core. The steep wall gradient means a higher wall shear stress.", s16)
mcq("pp-11", T, "The quantity $u^*=\\sqrt{\\tau_w/\\rho}$ used in the log law is the:", ["Friction velocity", "Free-stream velocity", "Average velocity", "Fluctuation RMS"], 0, "Log law: $\\bar u/u^*=2.5\\ln(yu^*/\\nu)+5.0$.", s16)
mcq("pp-12", T, "In fully developed turbulent pipe flow, the friction factor $f$ depends on:", ["Reynolds number and relative roughness $\\varepsilon/D$", "Reynolds number only", "Relative roughness only", "Pipe length only"], 0, "Laminar flow: $f=64/\\mathrm{Re}$ (no roughness effect). Fully rough turbulent flow: $f$ depends on $\\varepsilon/D$ only.", s16)
tf("pp-13", T, "Wall roughness has a negligible effect on the friction factor in laminar pipe flow.", True, "In laminar flow viscous effects span the whole pipe, so small roughness elements don't matter.", s16)
sa("pp-14", T, "Why does roughness matter in turbulent flow but not laminar flow?", "In turbulent flow the viscous sublayer is very thin, so roughness elements can poke through it into the turbulent region and disturb the flow. In laminar flow viscous effects fill the whole pipe and swamp small roughness.", "This leads to the classification: hydraulically smooth, transitionally rough, fully rough.", s16, ["thin viscous sublayer", "roughness protrudes", "laminar dominated by viscosity"])
mcq("pp-15", T, "At very high Re (fully rough regime) on the Moody chart, the friction factor:", ["Becomes independent of Re and depends only on $\\varepsilon/D$", "Keeps decreasing like $64/\\mathrm{Re}$", "Increases linearly with Re", "Goes to zero"], 0, "The Moody curves become horizontal to the right of the dashed line.", s16)
mcq("pp-16", T, "The Blasius correlation $f=0.316/\\mathrm{Re}^{1/4}$ applies to:", ["Turbulent flow in smooth pipes (Re ≲ 10⁵)", "Laminar flow", "Fully rough pipes", "Non-circular ducts only"], 0, "Colebrook (implicit) or Haaland (explicit) are used for rough pipes.", s16)
mcq("pp-17", T, "Major head loss in a pipe (Darcy–Weisbach) is:", ["$h_L=f\\dfrac{\\ell}{D}\\dfrac{V^2}{2g}$", "$h_L=K_L\\dfrac{V^2}{2g}$", "$h_L=\\dfrac{32\\mu\\ell V}{D}$", "$h_L=f\\dfrac{D}{\\ell}\\dfrac{V^2}{2g}$"], 0, "Minor losses use $h_L=K_L V^2/2g$, or an equivalent length $\\ell_{eq}=K_L D/f$.", s16)
tf("pp-18", T, "Bernoulli's equation can be applied directly to viscous pipe flow as long as the flow is steady.", False, "Bernoulli assumes frictionless flow. For real pipe flow, use the energy equation with head-loss terms $h_L$ (and pump or turbine heads).", s16)
mcq("pp-19", T, "The hydraulic diameter of a non-circular duct is:", ["$D_h=4A/P$ (four times area over wetted perimeter)", "$D_h=A/P$", "$D_h=2A/P$", "$D_h=\\sqrt{4A/\\pi}$"], 0, "For a circle $D_h=D$. For a square of side $a$, $D_h=a$.", s17)
mcq("pp-20", T, "In the energy equation for pipe flow, a pump appears as:", ["A head added, $+h_p$, on the upstream side (gain)", "A head loss, like friction", "A change in elevation", "It does not appear"], 0, "$\\frac{p_1}{\\gamma}+\\frac{V_1^2}{2g}+z_1+h_p=\\frac{p_2}{\\gamma}+\\frac{V_2^2}{2g}+z_2+h_T+h_L$. A turbine extracts head $h_T$.", s17)
tf("pp-21", T, "For pipes in series, the flow rate is the same in each pipe and the head losses add.", True, "For parallel pipes it's reversed: the head loss is the same in each branch and the flow rates add.", s17)
sa("pp-22", T, "For a single-pipe problem, which of the three classic unknowns ($\\Delta p$, $D$, or $Q$) can be found without iteration?", "$\\Delta p$ (or head loss) for given $L$, $D$, $Q$: compute Re and $f$, then apply the energy equation directly. Finding $D$ or $Q$ requires iteration, because $f$ depends on the unknown through Re and $\\varepsilon/D$.", "Iterate between the energy equation and Colebrook/Haaland (or the Moody chart).", s17, ["Δp direct", "D and Q iterate"])
tf("pp-23", T, "Pressure drop in fully developed pipe flow is proportional to pipe length.", True, "That is why $\\Delta p\\propto \\ell/D$ in Darcy–Weisbach.", s16)

T = "External flow & boundary layers (Ch 9)"; s18 = L(18, "Flow over Immersed Bodies"); s19 = L(19, "Flow over Immersed Bodies")
mcq("ex-01", T, "Drag is the component of the resultant fluid force:", ["Parallel to the upstream flow direction", "Perpendicular to the upstream flow", "Normal to the body surface", "Due only to shear stress"], 0, "Lift is perpendicular to the free stream.", s18)
sa("ex-02", T, "Lift and drag come from integrating which two surface quantities over a body?", "Pressure (acting normal to the surface) and wall shear stress (acting tangential to the surface).", "Drag = pressure (form) drag + friction drag.", s18, ["pressure", "wall shear stress"])
mcq("ex-03", T, "The drag coefficient is defined as:", ["$C_D=\\dfrac{F_D}{\\tfrac12\\rho U^2A}$", "$C_D=\\dfrac{F_D}{\\rho U^2A}$", "$C_D=\\dfrac{\\tfrac12\\rho U^2A}{F_D}$", "$C_D=\\dfrac{F_D}{\\rho U A}$"], 0, "Same form for $C_L$. $A$ is frontal area for bluff bodies and planform area for wings.", s18)
tf("ex-04", T, "The fluid forces on a body are the same whether the body moves through still fluid or the fluid moves past a stationary body at the same relative speed.", True, "Only relative motion matters, which is why wind tunnels work.", s18)
mcq("ex-05", T, "The boundary-layer thickness $\\delta$ is commonly defined as the distance from the wall where:", ["$u=0.99U$", "$u=0.5U$", "$u=U$ exactly", "The shear stress is maximum"], 0, "Displacement thickness $\\delta^*$ and momentum thickness $\\theta$ are integral measures.", s19)
mcq("ex-06", T, "For a laminar flat-plate boundary layer (Blasius), $\\delta$ grows like:", ["$\\delta\\approx5x/\\sqrt{\\mathrm{Re}_x}$, i.e. $\\propto\\sqrt x$", "$\\delta\\propto x$", "$\\delta\\propto x^{4/5}$", "$\\delta$ = constant"], 0, "A turbulent BL grows faster, roughly $\\delta\\approx0.37x/\\mathrm{Re}_x^{1/5}$, i.e. $\\propto x^{4/5}$.", s19)
mcq("ex-07", T, "Transition to turbulence on a smooth flat plate typically occurs near:", ["$\\mathrm{Re}_x\\approx5\\times10^5$", "$\\mathrm{Re}_x\\approx2100$", "$\\mathrm{Re}_x\\approx4000$", "$\\mathrm{Re}_x\\approx10^9$"], 0, "This varies from $2\\times10^5$ to $3\\times10^6$ depending on roughness and free-stream turbulence.", s19)
tf("ex-08", T, "Momentum thickness $\\theta$ represents the loss of momentum flux in the boundary layer compared with inviscid flow.", True, "$\\theta=\\int_0^\\infty \\frac uU(1-\\frac uU)dy$. It relates directly to drag on the plate.", s19)
tf("ex-09", T, "Wall shear stress on a flat plate in laminar flow decreases with distance from the leading edge.", True, "As $\\delta$ grows, the velocity gradient at the wall drops: $\\tau_w\\propto x^{-1/2}$.", s19)
mcq("ex-10", T, "For a streamlined body (e.g. a thin airfoil at small angle of attack), most of the drag is:", ["Friction drag", "Pressure (form) drag", "Wave drag", "Induced by separation"], 0, "Bluff bodies (cylinders, flat plates normal to the flow) are dominated by pressure drag from separation.", s19)
mcq("ex-11", T, "Boundary-layer separation is caused by:", ["An adverse pressure gradient ($dp/dx>0$) that decelerates slow near-wall fluid until $\\partial u/\\partial y=0$ at the wall", "A favourable pressure gradient", "High free-stream turbulence alone", "Compressibility"], 0, "Past the separation point there is reversed flow and a wake.", s19)
tf("ex-12", T, "A turbulent boundary layer resists separation better than a laminar one.", True, "Turbulent mixing brings high-momentum fluid toward the wall. This is why golf-ball dimples and trip wires reduce drag on bluff bodies.", s19)
mcq("ex-13", T, "The sudden drop in $C_D$ for a smooth sphere around Re ≈ 3×10⁵ happens because:", ["The boundary layer becomes turbulent, separation moves aft and the wake narrows", "The flow becomes laminar everywhere", "Friction drag disappears", "The sphere starts to rotate"], 0, "This is the drag crisis. Pressure drag falls a lot even though friction drag rises slightly.", s19)
tf("ex-14", T, "Golf-ball dimples reduce drag by causing an earlier transition to a turbulent boundary layer.", True, "This delays separation and shrinks the wake, giving lower pressure drag at typical drive speeds.", s19)
mcq("ex-15", T, "An airfoil stalls when, at high angle of attack:", ["The flow separates from the upper surface, lift drops and drag rises sharply", "The flow becomes supersonic", "The pressure on the lower surface drops", "The boundary layer becomes laminar"], 0, "This is why $C_L$ peaks at the stall angle. Lab 4 measured the airfoil $C_p$ distribution.", s19)
mcq("ex-16", T, "For creeping flow past a sphere (Re < 1), Stokes' law gives:", ["$F_D=3\\pi\\mu UD$, so $C_D=24/\\mathrm{Re}$", "$C_D\\approx0.47$", "$F_D\\propto U^2$", "$C_D=64/\\mathrm{Re}$"], 0, "Drag is linear in velocity because viscous forces dominate inertia.", s19)

T = "Compressible flow (Ch 11)"; s = "Course outline – Ch 11 (11.1–11.6)"
mcq("cf-01", T, "The speed of sound in an ideal gas is:", ["$c=\\sqrt{kRT}$", "$c=\\sqrt{RT}$", "$c=kRT$", "$c=\\sqrt{p/\\rho}$"], 0, "In air at 15 °C, $c\\approx340$ m/s. It depends only on temperature for a given gas.", s)
mcq("cf-02", T, "Flow is usually treated as incompressible when the Mach number is below about:", ["0.3", "1.0", "0.8", "0.05"], 0, "At $\\mathrm{Ma}<0.3$, density changes are under about 5%.", s)
tf("cf-03", T, "In isentropic subsonic flow through a converging duct, the velocity increases and the pressure decreases.", True, "Area–velocity relation: $\\frac{dA}{A}=(\\mathrm{Ma}^2-1)\\frac{dV}{V}$. For Ma < 1, $dA<0$ gives $dV>0$.", s)
tf("cf-04", T, "In supersonic flow, a diverging duct accelerates the flow.", True, "For Ma > 1, $(\\mathrm{Ma}^2-1)>0$, so $dA>0$ gives $dV>0$. This is why rockets use the diverging part of a nozzle.", s)
mcq("cf-05", T, "In isentropic flow, Ma = 1 can only occur:", ["At the throat (minimum area)", "At the inlet", "Anywhere in a diverging section", "At the exit of a converging section only when the back pressure is high"], 0, "To go from subsonic to supersonic you need a converging–diverging nozzle with sonic flow at the throat.", s)
sa("cf-06", T, "What does it mean for a converging nozzle to be choked?", "The flow reaches Ma = 1 at the exit (throat). Lowering the back pressure further cannot increase the mass flow rate, which stays at its maximum for the given stagnation conditions.", "Choked mass flow depends only on the stagnation pressure and temperature and the throat area.", s, ["Ma = 1 at throat", "max mass flow", "independent of back pressure"])
tf("cf-07", T, "Stagnation temperature stays constant in adiabatic flow of an ideal gas, even across a normal shock.", True, "$T_0=T(1+\\frac{k-1}2\\mathrm{Ma}^2)$ is conserved when no heat or work is added. Stagnation pressure, however, drops across a shock.", s)
mcq("cf-08", T, "Across a normal shock, the flow goes from:", ["Supersonic to subsonic, with a rise in static pressure and a loss of stagnation pressure", "Subsonic to supersonic", "Supersonic to more supersonic", "Subsonic to sonic, isentropically"], 0, "Shocks are irreversible: entropy rises, so $p_0$ falls.", s)
